version = "0.1.0"
edition = "2021"

src/lib.rs:
pub mod display;
pub mod repo;
pub mod sql;

src/repo.rs:
pub trait Repo { fn get(&self, id: &str) -> String; }

src/display.rs:
pub trait Display { fn show(&self) -> String; }

src/sql.rs:
use crate::repo::Repo;
use std::fmt::Display;
pub struct SqlRepo;
impl Repo for SqlRepo { fn get(&self, id: &str) -> String { id.to_string() } }
impl Display for SqlRepo { fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result { write!(f, "sql") } }
